package com.ccb.testmanagement.defect;

import com.ccb.attachment.integration.AttachmentBindingCommand;import com.ccb.attachment.integration.AttachmentGateway;import com.ccb.attachment.integration.AttachmentItem;import com.ccb.common.api.PageQuery;import com.ccb.common.api.PageResult;import com.ccb.common.exception.BusinessException;import com.ccb.common.exception.ErrorCode;import com.ccb.security.model.AuthUser;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;import java.util.concurrent.atomic.AtomicLong;

/** 缺陷服务持有状态机、实体授权和附件编排，Repository 负责参数化 SQL。 */
@Service public class TestDefectService {
 public static final String BUSINESS_TYPE="TEST_DEFECT";private static final Set<String> DOMAINS=Set.of("application-assembly","user-testing","non-functional","security"),STATUS=Set.of("RAISED","CAUSE_IDENTIFIED","FIX_PLAN_CONFIRMED","PENDING_VERIFICATION","RESOLVED"),CATEGORY=Set.of("FUNCTION","DATA","UI","PERFORMANCE","SECURITY","ENVIRONMENT","REQUIREMENT","OPERATION","OTHER"),LEVEL=Set.of("FATAL","SERIOUS","GENERAL","MINOR"),TRI=Set.of("HIGH","MEDIUM","LOW");private static final AtomicLong IDS=new AtomicLong(System.currentTimeMillis()*1000);private final TestDefectRepository repository;private final AttachmentGateway attachments;private final ObjectMapper mapper;
 public TestDefectService(TestDefectRepository repository,AttachmentGateway attachments,ObjectMapper mapper){this.repository=repository;this.attachments=attachments;this.mapper=mapper;}
 public Map<String,Object> tree(String d,long p,AuthUser u){project(d,p,u);Map<String,Object>x=base(d,p,u);return Map.of("systems",repository.systems(x),"rounds",repository.rounds(x),"cycles",repository.cycles(x),"environments",repository.environments(x),"handlers",repository.handlers(x));}
 public PageResult<Map<String,Object>> list(String d,long p,Long sys,String keyword,Collection<String> statuses,Collection<String> categories,Collection<String> severities,Collection<String> priorities,Collection<String> urgencies,Long handler,Long proposer,String link,boolean recycle,String quick,String sortBy,String sortOrder,PageQuery page,AuthUser u){project(d,p,u);if(sys!=null)system(d,p,sys,u.tenantId());Map<String,Object>x=base(d,p,u);x.put("systemId",sys);x.put("keyword",text(keyword,200,"关键字"));x.put("statuses",values(statuses,STATUS,"状态"));x.put("categories",values(categories,CATEGORY,"缺陷分类"));x.put("severities",values(severities,LEVEL,"严重程度"));x.put("priorities",values(priorities,TRI,"优先级"));x.put("urgencies",values(urgencies,TRI,"紧急程度"));x.put("handlerId",handler);x.put("proposerId",proposer);x.put("link",link==null?null:link.toUpperCase(Locale.ROOT));x.put("recycle",recycle);x.put("quick",quick==null?null:quick.toUpperCase(Locale.ROOT));if(x.get("quick")!=null&&!Set.of("SUBMITTED","HANDLED","VERIFY").contains(x.get("quick")))throw bad("快捷筛选无效");x.put("sortBy",sortBy);x.put("sortOrder",sortOrder);long total=repository.listCount(x);x.put("offset",(page.page()-1)*page.size());x.put("size",page.size());return new PageResult<>(repository.list(x),total,page.page(),page.size());}
 public List<Map<String,Object>> exportRows(String d,long p,Long sys,String keyword,Collection<String> statuses,Collection<String> categories,Collection<String> severities,Collection<String> priorities,Collection<String> urgencies,AuthUser u){return list(d,p,sys,keyword,statuses,categories,severities,priorities,urgencies,null,null,null,false,null,"proposed_at","descending",new PageQuery(1,2000),u).records();}
 @Transactional public Map<String,Object> create(String d,long p,Map<String,Object>b,AuthUser u){project(d,p,u);long sys=positive(b.get("physical_subsystem_id"),"所属系统");system(d,p,sys,u.tenantId());String summary=required(b.get("summary"),"概述",100),description=html(b.get("description_html"),"缺陷描述"),category=value(b.get("defect_category"),CATEGORY,"缺陷分类"),severity=value(b.get("severity"),LEVEL,"严重程度"),priority=value(b.get("priority"),TRI,"优先级"),urgency=value(b.get("urgency"),TRI,"紧急程度");Long handler=nullable(b.get("handler_id"));if(handler!=null)handler(d,p,sys,handler,u.tenantId());Map<String,Object> codeRow=repository.systemCode(params("systemId",sys,"tenantId",u.tenantId()));int serial=repository.nextSerial(params("systemId",sys,"tenantId",u.tenantId()));long id=next();String code="BUG"+codeRow.get("code")+"-"+String.format("%04d",serial);Map<String,Object>x=base(d,p,u);x.putAll(params("id",id,"systemId",sys,"defectCode",code,"serial",serial,"summary",summary,"description",description,"roundId",nullable(b.get("round_id")),"cycleId",nullable(b.get("cycle_id")),"category",category,"severity",severity,"priority",priority,"urgency",urgency,"foundVersion",text(b.get("found_version"),50,"发现版本"),"environment",text(b.get("test_environment_code"),64,"测试环境"),"handlerId",handler));repository.insert(x);associate(id,ids(b.get("execution_ids")),d,p,u);syncAttachments(id,b.get("attachment_ids"),u);trace(id,d,p,"CREATE",u,Map.of("defect_code",code));return detail(d,p,id,u);}
 @Transactional public Map<String,Object> update(String d,long p,long id,Map<String,Object>b,AuthUser u){Map<String,Object>old=row(id,d,p,u.tenantId());long sys=b.containsKey("physical_subsystem_id")?positive(b.get("physical_subsystem_id"),"所属系统"):number(old.get("physical_subsystem_id"));system(d,p,sys,u.tenantId());String summary=b.containsKey("summary")?required(b.get("summary"),"概述",100):String.valueOf(old.get("summary"));String description=b.containsKey("description_html")?html(b.get("description_html"),"缺陷描述"):String.valueOf(old.get("description_html"));String category=b.containsKey("defect_category")?value(b.get("defect_category"),CATEGORY,"缺陷分类"):String.valueOf(old.get("defect_category")),severity=b.containsKey("severity")?value(b.get("severity"),LEVEL,"严重程度"):String.valueOf(old.get("severity")),priority=b.containsKey("priority")?value(b.get("priority"),TRI,"优先级"):String.valueOf(old.get("priority")),urgency=b.containsKey("urgency")?value(b.get("urgency"),TRI,"紧急程度"):String.valueOf(old.get("urgency"));Long handler=b.containsKey("handler_id")?nullable(b.get("handler_id")):nullable(old.get("handler_id"));if(handler!=null)handler(d,p,sys,handler,u.tenantId());Map<String,Object>x=params("id",id,"tenantId",u.tenantId(),"userId",u.id(),"systemId",sys,"summary",summary,"description",description,"roundId",b.containsKey("round_id")?nullable(b.get("round_id")):nullable(old.get("round_id")),"cycleId",b.containsKey("cycle_id")?nullable(b.get("cycle_id")):nullable(old.get("cycle_id")),"category",category,"severity",severity,"priority",priority,"urgency",urgency,"foundVersion",b.containsKey("found_version")?text(b.get("found_version"),50,"发现版本"):old.get("found_version"),"environment",b.containsKey("test_environment_code")?text(b.get("test_environment_code"),64,"测试环境"):old.get("test_environment_code"),"handlerId",handler);repository.update(x);if(b.containsKey("attachment_ids"))syncAttachments(id,b.get("attachment_ids"),u);trace(id,d,p,"UPDATE",u,Map.of("summary",summary));return detail(d,p,id,u);}
 public Map<String,Object> detail(String d,long p,long id,AuthUser u){Map<String,Object>out=new LinkedHashMap<>(row(id,d,p,u.tenantId()));out.put("executions",repository.executions(params("tenantId",u.tenantId(),"defectId",id)));out.put("traces",repository.traces(params("tenantId",u.tenantId(),"defectId",id)));out.put("attachments",attachmentRows(id,u.tenantId()));return out;}
 @Transactional public Map<String,Object> transition(String d,long p,long id,String target,AuthUser u){Map<String,Object>f=row(id,d,p,u.tenantId());String to=value(target,STATUS,"目标状态"),from=String.valueOf(f.get("status"));if(!allowed(from,to))throw bad("当前缺陷状态不允许该流转");transitionAllowed(d,p,f,to,u);return updateStatus(id,d,p,to,u,from);}
 private Map<String,Object> updateStatus(long id,String d,long p,String to,AuthUser u,String from){repository.updateStatus(params("id",id,"tenantId",u.tenantId(),"status",to,"userId",u.id()));trace(id,d,p,"TRANSITION",u,Map.of("from",from,"to",to));return detail(d,p,id,u);}
 @Transactional public void associate(long defect,Collection<Long> executions,String d,long p,AuthUser u){if(executions.isEmpty())return;row(defect,d,p,u.tenantId());for(long execution:executions){Map<String,Object>x=params("tenantId",u.tenantId(),"executionId",execution,"domain",d,"projectId",p,"defectId",defect);if(!repository.executionExists(x))throw bad("执行记录不存在或不属于当前项目");if(!repository.relationExists(x)){x.put("id",next());x.put("userId",u.id());repository.insertRelation(x);}}trace(defect,d,p,"ASSOCIATE_EXECUTION",u,Map.of("execution_ids",executions));}
 @Transactional public void detach(long defect,long execution,String d,long p,AuthUser u){Map<String,Object>e=repository.executionSnapshot(params("executionId",execution,"tenantId",u.tenantId()));int changed=repository.detach(params("tenantId",u.tenantId(),"defectId",defect,"executionId",execution,"caseCode",e.get("case_code"),"caseName",e.get("case_name"),"scopeCode",e.get("scope_code"),"scopeName",e.get("scope_name"),"userId",u.id()));if(changed==0)throw bad("缺陷关联不存在");trace(defect,d,p,"DETACH_EXECUTION",u,Map.of("execution_id",execution));}
 @Transactional public void remove(String d,long p,long id,AuthUser u){row(id,d,p,u.tenantId());if(repository.activeLinks(params("tenantId",u.tenantId(),"defectId",id))>0)throw bad("存在关联执行记录的缺陷不可删除");repository.softDelete(params("tenantId",u.tenantId(),"defectId",id,"userId",u.id()));trace(id,d,p,"DELETE",u,Map.of());}
 @Transactional public void restore(String d,long p,long id,AuthUser u){project(d,p,u);Map<String,Object>x=params("tenantId",u.tenantId(),"domain",d,"projectId",p,"defectId",id,"userId",u.id());if(!repository.deletedExists(x))throw bad("缺陷不存在或已超过30天恢复期限");repository.restore(x);trace(id,d,p,"RESTORE",u,Map.of());}
 private void syncAttachments(long defect,Object raw,AuthUser u){Set<Long>wanted=new LinkedHashSet<>(ids(raw));for(Map<String,Object> item:attachmentRows(defect,u.tenantId())){long attachment=number(item.get("id"));if(!wanted.contains(attachment)){attachments.deleteBound(attachment,BUSINESS_TYPE,String.valueOf(defect),u);repository.deleteAttachment(params("tenantId",u.tenantId(),"defectId",defect,"attachmentId",attachment));}}int sort=0;for(long attachment:wanted){AttachmentItem item=attachments.get(attachment,u);if(item.fileSize()>50L*1024*1024)throw bad("单个附件不能超过50MB");Map<String,Object>x=params("tenantId",u.tenantId(),"defectId",defect,"attachmentId",attachment);if(!repository.attachmentExists(x)){attachments.bind(new AttachmentBindingCommand(attachment,BUSINESS_TYPE,String.valueOf(defect),null),u);x.put("id",next());x.put("sortNo",sort);x.put("userId",u.id());repository.insertAttachment(x);}sort++;}}
 private List<Map<String,Object>> attachmentRows(long id,long tenant){return repository.attachments(params("tenantId",tenant,"defectId",id));}private Map<String,Object> row(long id,String d,long p,long t){Map<String,Object>x=repository.row(params("id",id,"tenantId",t,"domain",d,"projectId",p));if(x==null||x.isEmpty())throw bad("缺陷不存在或不属于当前项目");return x;}private void project(String d,long p,AuthUser u){if(!DOMAINS.contains(d))throw bad("测试大类无效");if(!repository.projectExists(params("projectId",p,"tenantId",u.tenantId())))throw bad("项目不存在或无权访问");}private void system(String d,long p,long s,long t){if(!repository.participatingSystem(params("tenantId",t,"domain",d,"projectId",p,"systemId",s)))throw bad("请选择已启用的参测系统");}private void handler(String d,long p,long s,long id,long t){if(!repository.handlerAllowed(params("tenantId",t,"domain",d,"projectId",p,"systemId",s,"handlerId",id)))throw bad("处理人必须是所属系统的开发人员");}private void transitionAllowed(String d,long p,Map<String,Object>f,String to,AuthUser u){long s=number(f.get("physical_subsystem_id"));boolean manager=repository.hasRole(params("tenantId",u.tenantId(),"domain",d,"projectId",p,"systemId",s,"userId",u.id(),"roleCode","TEST_MANAGER")),developer=Objects.equals(nullable(f.get("handler_id")),u.id()),proposer=number(f.get("proposer_id"))==u.id(),elevated=authority("test-management:"+d+":defects:delete");if(elevated)return;if(Set.of("CAUSE_IDENTIFIED","FIX_PLAN_CONFIRMED","PENDING_VERIFICATION").contains(to)&&(developer||manager))return;if(Set.of("RESOLVED","RAISED").contains(to)&&(proposer||manager))return;throw new BusinessException(ErrorCode.FORBIDDEN,"无权执行当前缺陷状态流转");}private void trace(long id,String d,long p,String action,AuthUser u,Map<String,Object>data){try{repository.insertTrace(params("id",next(),"tenantId",u.tenantId(),"domain",d,"projectId",p,"defectId",id,"action",action,"userId",u.id(),"detailJson",mapper.writeValueAsString(data)));}catch(Exception e){throw new BusinessException(ErrorCode.INTERNAL_ERROR,"缺陷轨迹写入失败");}}
 private Map<String,Object>base(String d,long p,AuthUser u){return params("tenantId",u.tenantId(),"domain",d,"projectId",p,"userId",u.id());}private static boolean allowed(String from,String to){return switch(from){case "RAISED"->to.equals("CAUSE_IDENTIFIED");case "CAUSE_IDENTIFIED"->to.equals("FIX_PLAN_CONFIRMED");case "FIX_PLAN_CONFIRMED"->to.equals("PENDING_VERIFICATION");case "PENDING_VERIFICATION"->to.equals("RESOLVED")||to.equals("RAISED");case "RESOLVED"->to.equals("RAISED");default->false;};}private boolean authority(String value){var a=org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication();return a!=null&&a.getAuthorities().stream().anyMatch(x->value.equals(x.getAuthority()));}private static List<String>values(Collection<String>raw,Set<String>allowed,String label){if(raw==null)return List.of();List<String>out=new ArrayList<>();for(String v:raw)out.add(value(v,allowed,label));return out;}private static String value(Object x,Set<String>a,String l){String s=required(x,l,64).toUpperCase(Locale.ROOT);if(!a.contains(s))throw bad(l+"无效");return s;}private static String html(Object x,String l){String s=required(x,l,200000).replaceAll("(?is)<script[^>]*>.*?</script>","");if(s.replaceAll("<[^>]*>","").trim().isEmpty())throw bad(l+"不能为空");return s;}private static String required(Object x,String l,int max){String s=text(x,max,l);if(s==null)throw bad(l+"不能为空");return s;}private static String text(Object x,int max,String l){if(x==null)return null;String s=String.valueOf(x).trim();if(s.isEmpty()||"null".equals(s))return null;if(s.length()>max)throw bad(l+"不能超过"+max+"个字符");return s;}private static long positive(Object x,String l){Long n=nullable(x);if(n==null||n<=0)throw bad(l+"无效");return n;}private static Long nullable(Object x){if(x==null||String.valueOf(x).isBlank()||"null".equals(String.valueOf(x)))return null;try{return Long.parseLong(String.valueOf(x));}catch(Exception e){throw bad("编号无效");}}private static long number(Object x){return ((Number)x).longValue();}private static List<Long>ids(Object x){List<Long>o=new ArrayList<>();if(x instanceof Collection<?>c)for(Object v:c)o.add(positive(v,"编号"));return o;}private static long next(){return IDS.incrementAndGet();}private static Map<String,Object>params(Object...v){Map<String,Object>x=new HashMap<>();for(int i=0;i<v.length;i+=2)x.put(String.valueOf(v[i]),v[i+1]);return x;}private static BusinessException bad(String m){return new BusinessException(ErrorCode.BAD_REQUEST,m);}
}
